<template><div>
  <el-breadcrumb separator="/" class="crumb"><el-breadcrumb-item to="/admin/reports">管理决策专题</el-breadcrumb-item><el-breadcrumb-item>课程质量与教学运行</el-breadcrumb-item></el-breadcrumb>
  <h2 class="sa-page-title">课程质量与教学运行</h2><p class="sa-page-sub">从跨学期课程结果发现需要进一步核查的课程，再按需查看学期变化和已接入开课资源。</p>
  <el-alert type="info" :closable="false" show-icon title="课程结果不等于教学归因" :description="definition.boundary"/>
  <div class="filters"><el-select v-model="draftFrom" clearable placeholder="起始学期"><el-option v-for="s in data.semesters" :key="s" :label="s" :value="s"/></el-select><span>至</span><el-select v-model="draftTo" clearable placeholder="结束学期"><el-option v-for="s in data.semesters" :key="s" :label="s" :value="s"/></el-select><el-button type="primary" :loading="loading" @click="apply">应用筛选</el-button><span class="hint">趋势和开课资源仅在选择课程后加载</span></div>
  <el-skeleton :loading="initialLoading" animated :rows="4"><div class="kpis"><div v-for="x in kpis" :key="x.label" class="kpi"><span>{{x.label}} <el-tooltip :content="x.help"><i>?</i></el-tooltip></span><b>{{x.value}}</b><small>{{x.note}}</small></div></div></el-skeleton>
  <section class="sa-card" v-loading="loading"><div class="sa-card-title">需要进一步核查的课程 <span class="extra">关注原因可同时满足多项，不再强制归入单一类型</span></div><el-table :data="data.courses" stripe :row-class-name="rowClass"><el-table-column prop="course_name" label="课程" min-width="180"/><el-table-column prop="observed_terms" label="达到样本要求的学期数" width="145"/><el-table-column prop="student_term_count" label="修读学生人次" width="105"/><el-table-column prop="failures" label="未通过记录数" width="105"/><el-table-column label="成绩记录未通过率" width="130"><template #default="{row}">{{row.fail_rate}}%</template></el-table-column><el-table-column label="最高与最低学期差值" width="150"><template #default="{row}">{{row.volatility}} 个百分点</template></el-table-column><el-table-column prop="retake_attempts" label="重修记录人次" width="105"/><el-table-column label="关注原因" min-width="250"><template #default="{row}"><el-tag v-for="r in row.attention_reasons" :key="r" :type="tagType(r)" size="small" class="reason">{{reasonText(r,row)}}</el-tag></template></el-table-column><el-table-column label="操作" width="125" fixed="right"><template #default="{row}"><el-button link type="primary" :loading="detailLoading&&selected===row.course_id" @click="selectCourse(row)">{{selected===row.course_id?'正在查看':'查看学期变化'}}</el-button></template></el-table-column></el-table><el-pagination v-if="data.total" v-model:current-page="page" :page-size="50" :total="data.total" layout="total, prev, pager, next" @current-change="load"/></section>
  <section ref="detailSection" class="sa-card detail" v-loading="detailLoading"><template v-if="selected"><div class="sa-card-title">{{detail.course_name}}｜学期结果与开课资源</div><div class="grid"><div><h4>学期变化</h4><el-table :data="detail.trends" size="small"><el-table-column prop="semester_id" label="学期"/><el-table-column prop="students" label="学生数"/><el-table-column prop="avg_score" label="平均分"/><el-table-column label="未通过率"><template #default="{row}">{{row.fail_rate}}%</template></el-table-column><el-table-column prop="retake_attempts" label="重修记录"/></el-table></div><div><h4>该课程已接入开课资源</h4><el-empty v-if="!detail.offerings?.length" description="当前接入教学任务中未找到该课程" :image-size="70"/><el-table v-else :data="detail.offerings" size="small"><el-table-column prop="semester_id" label="学期"/><el-table-column prop="lesson_count" label="教学班"/><el-table-column prop="teacher_count" label="教师"/><el-table-column prop="enrolled" label="选课人数"/><el-table-column prop="avg_class_size" label="平均班额"/></el-table><p class="hint">{{detail.offering_boundary}}</p></div></div></template><el-empty v-else description="请在上方选择一门课程查看学期变化与开课资源" :image-size="80"/></section>
  <section class="sa-card definition"><div class="sa-card-title">指标口径与管理含义</div><p><b>达到统计样本要求的课程：</b>{{definition.sample}}</p><p><b>成绩记录未通过率：</b>{{definition.overall}}</p><p><b>连续高未通过：</b>{{definition.persistent_high}}</p><p><b>学期间变化较大：</b>{{definition.volatile}}</p><p><b>影响面较广：</b>{{definition.wide_impact}} <b>重修记录较多：</b>{{definition.retake_pressure}}</p></section>
</div></template>
<script setup lang="ts">import{computed,nextTick,onMounted,reactive,ref}from'vue';import{http}from'@/utils/http';const loading=ref(false),initialLoading=ref(true),detailLoading=ref(false),draftFrom=ref(''),draftTo=ref(''),from=ref(''),to=ref(''),page=ref(1),selected=ref(''),detailSection=ref<HTMLElement>(),requestId=ref(0);const data=reactive<any>({summary:{},courses:[],semesters:[],total:0}),detail=reactive<any>({course_name:'',trends:[],offerings:[]}),definition=reactive<any>({});const kpis=computed(()=>[{label:'达到统计样本要求的课程',value:(data.summary.observed_courses||0)+' 门',note:'至少一个学期满足样本量',help:definition.sample||''},{label:'成绩记录未通过率',value:(data.summary.overall_fail_rate||0)+'%',note:(data.summary.failures||0)+' / '+(data.summary.attempts||0)+' 条',help:definition.overall||''},{label:'连续高未通过课程',value:(data.summary.persistent_high_courses||0)+' 门',note:'每个可比学期均≥15%',help:definition.persistent_high||''},{label:'学期间变化较大课程',value:(data.summary.volatile_courses||0)+' 门',note:'最大差值≥15个百分点',help:definition.volatile||''},{label:'累计重修记录',value:(data.summary.retake_attempts||0)+' 人次',note:'同一学生多次会重复计数',help:'筛选范围内重修成绩记录数量，用于评估重修资源压力。'}]);function tagType(r:string){return r==='persistent_high'?'danger':r==='wide_impact'?'warning':'info'}function reasonText(r:string,row:any){return r==='persistent_high'?`连续${row.observed_terms}学期≥15%`:r==='volatile'?`学期间相差${row.volatility}个百分点`:r==='wide_impact'?`累计未通过${row.failures}人次`:`重修${row.retake_attempts}人次`}function rowClass({row}:any){return row.course_id===selected.value?'selected-row':''}function apply(){from.value=draftFrom.value;to.value=draftTo.value;page.value=1;selected.value='';load()}async function load(){const id=++requestId.value;loading.value=true;try{const q=new URLSearchParams({limit:'50',offset:String((page.value-1)*50),min_sample:'30'});if(from.value)q.set('semester_from',from.value);if(to.value)q.set('semester_to',to.value);const r=await http.get<any>('/v2/topics/course-quality?'+q);if(id!==requestId.value)return;Object.assign(data,r);Object.assign(definition,r.definition)}finally{if(id===requestId.value){loading.value=false;initialLoading.value=false}}}async function selectCourse(row:any){selected.value=row.course_id;detailLoading.value=true;try{const q=new URLSearchParams();if(from.value)q.set('semester_from',from.value);if(to.value)q.set('semester_to',to.value);const r=await http.get<any>(`/v2/topics/course-quality/${encodeURIComponent(row.course_id)}/detail?${q}`);Object.assign(detail,r);await nextTick();detailSection.value?.scrollIntoView({behavior:'smooth',block:'start'})}finally{detailLoading.value=false}}onMounted(load)</script>
<style scoped>.crumb{margin-bottom:8px}.filters{display:flex;gap:10px;align-items:center;margin:14px 0}.filters .el-select{width:165px}.hint{font-size:12px;color:#94a3b8}.kpis{display:grid;grid-template-columns:repeat(5,1fr);gap:12px;margin-bottom:14px}.kpi{background:#fff;border:1px solid #e2e8f0;border-radius:10px;padding:15px}.kpi span,.kpi small{display:block;color:#64748b}.kpi b{display:block;font-size:24px;margin:6px 0}.kpi i{display:inline-flex;align-items:center;justify-content:center;width:16px;height:16px;border-radius:50%;background:#e2e8f0;font-style:normal}.sa-card{margin-bottom:14px}.reason{margin:2px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:18px}.detail{scroll-margin-top:20px}.detail h4{margin:4px 0 10px}.definition p{font-size:13px;color:#475569;line-height:1.8}.el-pagination{justify-content:flex-end;margin-top:12px}:deep(.selected-row td){background:#eef2ff!important}@media(max-width:1100px){.kpis{grid-template-columns:repeat(2,1fr)}.grid{grid-template-columns:1fr}}</style>
